# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.21.1/ankra-cli-darwin-arm64"
      sha256 "182aa1885ce4e887c3f32e5e7f3a27b1a2ab712d50be9a49f69cf36df9ecc317"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.21.1/ankra-cli-darwin-amd64"
      sha256 "6c7c75c8305cc678aeb92acba9e4a53f12e38c117a8c6914fe8699980ed76253"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.21.1/ankra-cli-linux-arm64"
      sha256 "4e50d6dc1465bf816fe1f8da4662f939fadc455c8d7cde8b1571f1d84400b7bd"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.21.1/ankra-cli-linux-amd64"
